import { EChart, type EChartSetup } from "@/components/ui/echart"
import "echarts-gl"

// Adapted from the Apache ECharts example "Simple Surface" (Apache-2.0):
// https://echarts.apache.org/examples/en/editor.html?c=simple-surface
const setup: EChartSetup = () => {
  let option: any
  option = {
    tooltip: {},
    backgroundColor: '#fff',
    visualMap: {
      show: false,
      dimension: 2,
      min: -1,
      max: 1,
      inRange: {
        color: [
          '#313695',
          '#4575b4',
          '#74add1',
          '#abd9e9',
          '#e0f3f8',
          '#ffffbf',
          '#fee090',
          '#fdae61',
          '#f46d43',
          '#d73027',
          '#a50026'
        ]
      }
    },
    xAxis3D: {
      type: 'value'
    },
    yAxis3D: {
      type: 'value'
    },
    zAxis3D: {
      type: 'value'
    },
    grid3D: {
      viewControl: {
        // projection: 'orthographic'
      }
    },
    series: [
      {
        type: 'surface',
        wireframe: {
          // show: false
        },
        equation: {
          x: {
            step: 0.05
          },
          y: {
            step: 0.05
          },
          z: function (x: any, y: any) {
            if (Math.abs(x) < 0.1 && Math.abs(y) < 0.1) {
              return '-';
            }
            return Math.sin(x * Math.PI) * Math.sin(y * Math.PI);
          }
        }
      }
    ]
  };
  return option
}

export function EchartsSimpleSurface() {
  return <EChart setup={setup} />
}
